  ["LKH"] = "<munch>",
  ["LKI"] = "",
  ["LKJ"] = "Hello, hello, |PLAYERNAME|! Please come in, look, and buy! I'm a specialist for all sorts of {tools}. Just ask me for a {trade} to see my offers! You can also ask me for general {hints} about the game. ...",
  ["LKK"] = "You can also ask me about each {citizen} of the isle.",
