  ["LLV"] = "npc.bozo.mission_3_t1 \\z\n\tnpc.bozo.mission_3_t2 \\z\n\tnpc.bozo.mission_3_t3",
  ["LLW"] = "npc.bozo.mission_4_t1_1 \\z\n\tnpc.bozo.mission_4_t1_2 \\z\n\tnpc.bozo.mission_4_t1_3 \\z\n\tnpc.bozo.mission_4_t1_4",
  ["LLX"] = "npc.bozo.mission_5_t1 \\z\n\tnpc.bozo.mission_5_t2 \\z\n\tnpc.bozo.mission_5_t3_1 \\z\n\tnpc.bozo.mission_5_t3_2 \\z\n\tnpc.bozo.mission_5_t3_3",
