  ["Ozy"] = "04 The grave in Cormaya",
  ["Ozz"] = "Find the grave in Cormaya.",
  ["P0"] = "My name is Captain Seahorse from the Royal Tibia Line.",
  ["P1"] = "This is Edron. Where do you want to go?",
  ["P2"] = "I'm sorry, but we don't serve this route. However, I heard that Wyrdin here in Edron is looking for adventurers to go on a trip to Yalahar for him.",
  ["P3"] = "I'm sorry but I don't sail there.",
  ["P4"] = "My ship is the fastest in the whole world.",
  ["P5"] = "Where do you want to go? To {Darashia}, {Venore}, {Liberty Bay}, {Port Hope}, {Yalahar} or {Edron}? Or to {Travora} - the island between the worlds?",
  ["P6"] = "We would like to welcome you on board.",
  ["P7"] = "Where do you want to go? To {Darashia}, {Venore}, {Liberty Bay}, {Port Hope}, {Yalahar} or {Edron}? Or to {Travora} - the island between the worlds?",
  ["P8"] = "Where do you want to go? To {Darashia}, {Venore}, {Liberty Bay}, {Port Hope}, {Yalahar} or {Edron}? Or to {Travora} - the island between the worlds?",
  ["P9"] = "Where do you want to go? To {Darashia}, {Venore}, {Liberty Bay}, {Port Hope}, {Yalahar} or {Edron}? Or to {Travora} - the island between the worlds?",
  ["PA"] = "Welcome on board, noble |PLAYERNAME|. I can bring you back to {Liberty Bay}. Do you want me to do it?",
  ["PB"] = "I am the captain of this ship.",
  ["PD"] = "Whoah. That was a large shadow passing by.",
  ["PF"] = "I am the captain of this ship.",
