  ["PL"] = "Do you seek a passage to Darashia for |TRAVELCOST|?",
  ["PM"] = "I warn you! This route is haunted by a ghostship. Do you really want to go there?",
  ["PN"] = "We would like to serve you some time.",
  ["PO"] = "We would like to serve you some time.",
  ["PP"] = "Where do you want to go? To {Edron}, {Darashia}, {Oramond} or {Venore}?",
